"""Durable job storage shared by the API server and the worker.

Each job is a single JSON file on disk in JOBS_DIR, named by a reversible
filesystem-safe encoding of the opaque job id. Writes are atomic (temp file
+ fsync + rename) so work survives crashes and host reboots.
"""

import json
import os
import re
import tempfile

JOBS_DIR = os.environ.get("JOBS_DIR", "/var/lib/job-worker/jobs")
ACCEPTED_DIR = os.environ.get("ACCEPTED_DIR", "/var/lib/accepted-jobs")

_SAFE = frozenset(
    "abcdefghijklmnopqrstuvwxyz"
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "0123456789.-"
)


def encode_id(jid):
    """Encode an arbitrary opaque id into a filesystem-safe filename part."""
    out = []
    for ch in jid:
        if ch in _SAFE:
            out.append(ch)
        else:
            out.append("=" + format(ord(ch), "04x"))
    return "".join(out)


def decode_name(name):
    """Reverse encode_id()."""
    if name.endswith(".json"):
        name = name[: -len(".json")]
    out = []
    i = 0
    n = len(name)
    while i < n:
        c = name[i]
        if c == "=":
            out.append(chr(int(name[i + 1 : i + 5], 16)))
            i += 5
        else:
            out.append(c)
            i += 1
    return "".join(out)


def init():
    os.makedirs(JOBS_DIR, exist_ok=True)


def job_path(jid):
    return os.path.join(JOBS_DIR, encode_id(jid) + ".json")


def read_job(jid):
    p = job_path(jid)
    if not os.path.exists(p):
        return None
    try:
        with open(p, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError):
        return None


def write_job(jid, rec):
    p = job_path(jid)
    data = json.dumps(rec, separators=(",", ":"), ensure_ascii=True)
    fd, tmp = tempfile.mkstemp(dir=JOBS_DIR, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, p)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def list_jobs():
    if not os.path.isdir(JOBS_DIR):
        return []
    out = []
    for name in os.listdir(JOBS_DIR):
        if not name.endswith(".json") or name.startswith(".tmp-"):
            continue
        p = os.path.join(JOBS_DIR, name)
        if not os.path.isfile(p):
            continue
        jid = decode_name(name)
        rec = read_job(jid)
        if rec is not None:
            out.append(rec)
    return out


def import_accepted():
    """Adopt opaque jobs accepted before deployment, exactly once.

    Copies any record in ACCEPTED_DIR not already present in our store.
    Original files are left untouched.
    """
    if not os.path.isdir(ACCEPTED_DIR):
        return 0
    imported = 0
    for name in os.listdir(ACCEPTED_DIR):
        if not name.endswith(".json"):
            continue
        p = os.path.join(ACCEPTED_DIR, name)
        if not os.path.isfile(p):
            continue
        try:
            with open(p, "r", encoding="utf-8") as f:
                rec = json.load(f)
        except (json.JSONDecodeError, OSError):
            continue
        jid = rec.get("id")
        if not jid:
            continue
        if read_job(jid) is not None:
            continue
        payload = rec.get("payload", "")
        write_job(
            jid,
            {
                "id": jid,
                "payload": payload,
                "status": "accepted",
                "result": None,
                "attempts": 0,
            },
        )
        imported += 1
    return imported

"""HTTP job API server. Serves the public contract on port 8080."""

import json
import os
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import store  # noqa: E402

PORT = int(os.environ.get("JOB_API_PORT", "8080"))


class Handler(BaseHTTPRequestHandler):
    server_version = "JobServe/1.0"

    def _send(self, code, body=b"", ctype="text/plain; charset=utf-8"):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _read_body(self):
        length = self.headers.get("Content-Length")
        if length is None:
            return b""
        try:
            return self.rfile.read(int(length))
        except Exception:
            return b""

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == "/health":
            self._send(200, "ready")
            return
        if path.startswith("/jobs/"):
            jid = unquote(path[len("/jobs/") :])
            rec = store.read_job(jid)
            if rec is None:
                self._send(
                    404,
                    json.dumps(
                        {"error": "not found", "id": jid},
                        separators=(",", ":"),
                    ),
                )
                return
            rec = dict(rec)
            out = {
                "id": rec.get("id", jid),
                "payload": rec.get("payload", ""),
                "status": rec.get("status", "accepted"),
                "result": rec.get("result"),
                "attempts": rec.get("attempts", 0),
            }
            self._send(200, json.dumps(out, separators=(",", ":")), "application/json")
            return
        self._send(404, json.dumps({"error": "not found"}))

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path.startswith("/jobs/"):
            jid = unquote(path[len("/jobs/") :])
            if not jid:
                self._send(400, json.dumps({"error": "empty id"}))
                return
            payload = self._read_body()
            if isinstance(payload, bytes):
                payload = payload.decode("utf-8", errors="surrogateescape")
            store.write_job(
                jid,
                {
                    "id": jid,
                    "payload": payload,
                    "status": "accepted",
                    "result": None,
                    "attempts": 0,
                },
            )
            self._send(202, "")
            return
        self._send(404, json.dumps({"error": "not found"}))

    def log_message(self, fmt, *args):
        sys.stderr.write("%s - %s\n" % (self.address_string(), fmt % args))


def main():
    store.init()
    imported = store.import_accepted()
    if imported:
        sys.stderr.write("imported %d pre-accepted job(s)\n" % imported)
    httpd = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    sys.stderr.write("job-api listening on %d\n" % PORT)
    httpd.serve_forever()


if __name__ == "__main__":
    main()

